package com.fluxcore.fluxcore_erp.api;
import com.fluxcore.fluxcore_erp.domain.Cliente; import com.fluxcore.fluxcore_erp.repository.ClienteRepository; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/clientes") public class ClienteController {private final ClienteRepository repo; public ClienteController(ClienteRepository r){repo=r;} @GetMapping List<Cliente> listar(){return repo.findAllByOrderByNomeAsc();} @PostMapping @ResponseStatus(HttpStatus.CREATED) Cliente criar(@Valid @RequestBody Cliente x){return repo.save(x);} @PutMapping("/{id}") Cliente atualizar(@PathVariable Long id,@Valid @RequestBody Cliente x){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void excluir(@PathVariable Long id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);repo.deleteById(id);}}
